/**
 * Artifact
 *
 * An artifact
 */
export type Artifact =
  & Record<string, unknown>
  & ({
    "archive_download_url": string;
    "created_at": null | string;
    /**
     * The SHA256 digest of the artifact. This field will only be populated on artifacts uploaded with upload-artifact v4 or newer. For older versions, this field will be null.
     */
    "digest"?: null | string;
    /**
     * Whether or not the artifact has expired.
     */
    "expired": boolean;
    "expires_at": null | string;
    "id": RestInt64;
    /**
     * The name of the artifact.
     */
    "name": string;
    "node_id": string;
    /**
     * The size in bytes of the artifact.
     */
    "size_in_bytes": RestInt64;
    "updated_at": null | string;
    "url": string;
    "workflow_run"?:
      | (Record<string, unknown> & {
        "head_branch"?: string;
        "head_repository_id"?: RestInt64;
        "head_sha"?: string;
        "id"?: RestInt64;
        "repository_id"?: RestInt64;
      })
      | null;
  });

/**
 * Artifact Deployment Record
 *
 * Artifact Metadata Deployment Record
 */
export type ArtifactDeploymentRecord =
  & Record<string, unknown>
  & ({
    /**
     * The ID of the provenance attestation associated with the deployment record.
     */
    "attestation_id"?: RestInt64 | null;
    "cluster"?: string;
    "created_at"?: string;
    "deployment_name"?: string;
    "digest"?: string;
    "id"?: RestInt64;
    "logical_environment"?: string;
    "physical_environment"?: string;
    /**
     * A list of runtime risks associated with the deployment.
     */
    "runtime_risks"?: Array<
      "critical-resource" | "internet-exposed" | "lateral-movement" | "sensitive-data"
    >;
    "tags"?: Record<string, string>;
    "updated_at"?: string;
  });

