/**
 * CheckRun
 *
 * A check performed on the code of a given code change
 */
export type CheckRun =
  & Record<string, unknown>
  & ({
    "app": NullableIntegration;
    "check_suite":
      | (Record<string, unknown> & {
        "id": RestInt64;
      })
      | null;
    "completed_at": null | string;
    "conclusion":
      | "action_required"
      | "cancelled"
      | "failure"
      | "neutral"
      | "skipped"
      | "success"
      | "timed_out"
      | null;
    "deployment"?: DeploymentSimple;
    "details_url": null | string;
    "external_id": null | string;
    /**
     * The SHA of the commit that is being checked.
     */
    "head_sha": string;
    "html_url": null | string;
    /**
     * The id of the check.
     */
    "id": RestInt64;
    /**
     * The name of the check.
     */
    "name": string;
    "node_id": string;
    "output":
      & Record<string, unknown>
      & ({
        "annotations_count": RestInt64;
        "annotations_url": string;
        "summary": null | string;
        "text": null | string;
        "title": null | string;
      });
    /**
     * Pull requests that are open with a `head_sha` or `head_branch` that matches the check. The returned pull requests do not necessarily indicate pull requests that triggered the check.
     */
    "pull_requests": Array<PullRequestMinimal>;
    "started_at": null | string;
    /**
     * The phase of the lifecycle that the check is currently in. Statuses of waiting, requested, and pending are reserved for GitHub Actions check runs.
     */
    "status": "completed" | "in_progress" | "pending" | "queued" | "requested" | "waiting";
    "url": string;
  });

/**
 * CheckRun
 *
 * A check performed on the code of a given code change
 */
export type CheckRunWithSimpleCheckSuite =
  & Record<string, unknown>
  & ({
    "app": Integration;
    "check_suite": SimpleCheckSuite;
    "completed_at": null | string;
    "conclusion":
      | "action_required"
      | "cancelled"
      | "failure"
      | "neutral"
      | "pending"
      | "skipped"
      | "stale"
      | "startup_failure"
      | "success"
      | "timed_out"
      | "waiting"
      | null;
    "deployment"?: DeploymentSimple;
    "details_url": string;
    "external_id": string;
    /**
     * The SHA of the commit that is being checked.
     */
    "head_sha": string;
    "html_url": string;
    /**
     * The id of the check.
     */
    "id": RestInt64;
    /**
     * The name of the check.
     */
    "name": string;
    "node_id": string;
    "output":
      & Record<string, unknown>
      & ({
        "annotations_count": RestInt64;
        "annotations_url": string;
        "summary": null | string;
        "text": null | string;
        "title": null | string;
      });
    "pull_requests": Array<PullRequestMinimal>;
    "started_at": string;
    /**
     * The phase of the lifecycle that the check is currently in.
     */
    "status": "completed" | "in_progress" | "pending" | "queued";
    "url": string;
  });

/**
 * CheckSuite
 *
 * A suite of checks performed on the code of a given code change
 */
export type CheckSuite =
  & Record<string, unknown>
  & ({
    "after": null | string;
    "app": NullableIntegration;
    "before": null | string;
    "check_runs_url": string;
    "conclusion":
      | "action_required"
      | "cancelled"
      | "failure"
      | "neutral"
      | "skipped"
      | "stale"
      | "startup_failure"
      | "success"
      | "timed_out"
      | null
      | null;
    "created_at": null | string;
    "head_branch": null | string;
    "head_commit": SimpleCommit;
    /**
     * The SHA of the head commit that is being checked.
     */
    "head_sha": string;
    "id": RestInt64;
    "latest_check_runs_count": RestInt64;
    "node_id": string;
    "pull_requests": Array<PullRequestMinimal> | null;
    "repository": MinimalRepository;
    "rerequestable"?: boolean;
    "runs_rerequestable"?: boolean;
    /**
     * The phase of the lifecycle that the check suite is currently in. Statuses of waiting, requested, and pending are reserved for GitHub Actions check suites.
     */
    "status": "completed" | "in_progress" | "pending" | "queued" | "requested" | "waiting" | null;
    "updated_at": null | string;
    "url": null | string;
  });

