/**
 * A code security configuration
 */
export type CodeSecurityConfiguration =
  & Record<string, unknown>
  & ({
    /**
     * The enablement status of GitHub Advanced Security
     */
    "advanced_security"?: "code_security" | "disabled" | "enabled" | "secret_protection";
    /**
     * The enablement status of code scanning default setup
     */
    "code_scanning_default_setup"?: "disabled" | "enabled" | "not_set";
    /**
     * Feature options for code scanning default setup
     */
    "code_scanning_default_setup_options"?:
      | (
        & Record<string, unknown>
        & ({
          /**
           * The label of the runner to use for code scanning when runner_type is 'labeled'.
           */
          "runner_label"?: null | string;
          /**
           * Whether to use labeled runners or standard GitHub runners.
           */
          "runner_type"?: "labeled" | "not_set" | "standard" | null;
        })
      )
      | null;
    /**
     * The enablement status of code scanning delegated alert dismissal
     */
    "code_scanning_delegated_alert_dismissal"?: "disabled" | "enabled" | "not_set";
    /**
     * Feature options for code scanning
     */
    "code_scanning_options"?:
      | (
        & Record<string, unknown>
        & ({
          /**
           * Whether to allow repos which use advanced setup
           */
          "allow_advanced"?: boolean | null;
        })
      )
      | null;
    "created_at"?: string;
    /**
     * The enablement status of Dependabot alerts
     */
    "dependabot_alerts"?: "disabled" | "enabled" | "not_set";
    /**
     * The enablement status of Dependabot delegated alert dismissal
     */
    "dependabot_delegated_alert_dismissal"?: "disabled" | "enabled" | "not_set" | null;
    /**
     * The enablement status of Dependabot security updates
     */
    "dependabot_security_updates"?: "disabled" | "enabled" | "not_set";
    /**
     * The enablement status of Dependency Graph
     */
    "dependency_graph"?: "disabled" | "enabled" | "not_set";
    /**
     * The enablement status of Automatic dependency submission
     */
    "dependency_graph_autosubmit_action"?: "disabled" | "enabled" | "not_set";
    /**
     * Feature options for Automatic dependency submission
     */
    "dependency_graph_autosubmit_action_options"?: Record<string, unknown> & {
      /**
       * Whether to use runners labeled with 'dependency-submission' or standard GitHub runners.
       */
      "labeled_runners"?: boolean;
    };
    /**
     * A description of the code security configuration
     */
    "description"?: null | string;
    /**
     * The enforcement status for a security configuration
     */
    "enforcement"?: "enforced" | "unenforced";
    /**
     * The URL of the configuration
     */
    "html_url"?: string;
    /**
     * The ID of the code security configuration
     */
    "id"?: RestInt64;
    /**
     * The name of the code security configuration. Must be unique within the organization.
     */
    "name"?: string;
    /**
     * The enablement status of private vulnerability reporting
     */
    "private_vulnerability_reporting"?: "disabled" | "enabled" | "not_set";
    /**
     * The enablement status of secret scanning
     */
    "secret_scanning"?: "disabled" | "enabled" | "not_set";
    /**
     * The enablement status of secret scanning delegated alert dismissal
     */
    "secret_scanning_delegated_alert_dismissal"?: "disabled" | "enabled" | "not_set";
    /**
     * The enablement status of secret scanning delegated bypass
     */
    "secret_scanning_delegated_bypass"?: "disabled" | "enabled" | "not_set";
    /**
     * Feature options for secret scanning delegated bypass
     */
    "secret_scanning_delegated_bypass_options"?:
      & Record<string, unknown>
      & ({
        /**
         * The bypass reviewers for secret scanning delegated bypass
         */
        "reviewers"?: Array<
          & Record<string, unknown>
          & ({
            /**
             * The bypass mode for the reviewer
             */
            "mode"?: "ALWAYS" | "EXEMPT";
            /**
             * The ID of the team or role selected as a bypass reviewer
             */
            "reviewer_id": RestInt64;
            /**
             * The type of the bypass reviewer
             */
            "reviewer_type": "ROLE" | "TEAM";
            /**
             * The ID of the security configuration associated with this bypass reviewer
             */
            "security_configuration_id"?: RestInt64;
          })
        >;
      });
    /**
     * The enablement status of secret scanning extended metadata
     */
    "secret_scanning_extended_metadata"?: "disabled" | "enabled" | "not_set";
    /**
     * The enablement status of Copilot secret scanning
     */
    "secret_scanning_generic_secrets"?: "disabled" | "enabled" | "not_set";
    /**
     * The enablement status of secret scanning non-provider patterns
     */
    "secret_scanning_non_provider_patterns"?: "disabled" | "enabled" | "not_set";
    /**
     * The enablement status of secret scanning push protection
     */
    "secret_scanning_push_protection"?: "disabled" | "enabled" | "not_set";
    /**
     * The enablement status of secret scanning validity checks
     */
    "secret_scanning_validity_checks"?: "disabled" | "enabled" | "not_set";
    /**
     * The type of the code security configuration.
     */
    "target_type"?: "enterprise" | "global" | "organization";
    "updated_at"?: string;
    /**
     * The URL of the configuration
     */
    "url"?: string;
  });

