/**
 * A GitHub Security Advisory.
 */
export type GlobalAdvisory = {
  /**
   * The users who contributed to the advisory.
   */
  readonly "credits":
    | (Array<
      Record<string, unknown> & {
        "type": SecurityAdvisoryCreditTypes;
        "user": SimpleUser;
      }
    >)
    | null;
  /**
   * The Common Vulnerabilities and Exposures (CVE) ID.
   */
  readonly "cve_id": null | string;
  "cvss":
    | (
      & Record<string, unknown>
      & ({
        /**
         * The CVSS score.
         */
        readonly "score": RestJsonNumber | null;
        /**
         * The CVSS vector.
         */
        "vector_string": null | string;
      })
    )
    | null;
  "cvss_severities"?: CvssSeverities;
  "cwes":
    | (Array<
      Record<string, unknown> & {
        /**
         * The Common Weakness Enumeration (CWE) identifier.
         */
        "cwe_id": string;
        /**
         * The name of the CWE.
         */
        readonly "name": string;
      }
    >)
    | null;
  /**
   * A detailed description of what the advisory entails.
   */
  "description": null | string;
  "epss"?: SecurityAdvisoryEpss;
  /**
   * The GitHub Security Advisory ID.
   */
  readonly "ghsa_id": string;
  /**
   * The date and time of when the advisory was reviewed by GitHub, in ISO 8601 format.
   */
  readonly "github_reviewed_at": null | string;
  /**
   * The URL for the advisory.
   */
  readonly "html_url": string;
  readonly "identifiers":
    | (Array<
      & Record<string, unknown>
      & ({
        /**
         * The type of identifier.
         */
        "type": "CVE" | "GHSA";
        /**
         * The identifier value.
         */
        "value": string;
      })
    >)
    | null;
  /**
   * The date and time when the advisory was published in the National Vulnerability Database, in ISO 8601 format.
   * This field is only populated when the advisory is imported from the National Vulnerability Database.
   */
  readonly "nvd_published_at": null | string;
  /**
   * The date and time of when the advisory was published, in ISO 8601 format.
   */
  readonly "published_at": string;
  "references": Array<string> | null;
  /**
   * The API URL for the repository advisory.
   */
  readonly "repository_advisory_url": null | string;
  /**
   * The severity of the advisory.
   */
  "severity": "critical" | "high" | "low" | "medium" | "unknown";
  /**
   * The URL of the advisory's source code.
   */
  "source_code_location": null | string;
  /**
   * A short summary of the advisory.
   */
  "summary": string;
  /**
   * The type of advisory.
   */
  readonly "type": "malware" | "reviewed" | "unreviewed";
  /**
   * The date and time of when the advisory was last updated, in ISO 8601 format.
   */
  readonly "updated_at": string;
  /**
   * The API URL for the advisory.
   */
  readonly "url": string;
  /**
   * The products and respective version ranges affected by the advisory.
   */
  "vulnerabilities": Array<Vulnerability> | null;
  /**
   * The date and time of when the advisory was withdrawn, in ISO 8601 format.
   */
  readonly "withdrawn_at": null | string;
};

