/**
 * status event
 */
export type WebhookStatus =
  & Record<string, unknown>
  & ({
    "avatar_url"?: null | string;
    /**
     * An array of branch objects containing the status' SHA. Each branch contains the given SHA, but the SHA may or may not be the head of the branch. The array includes a maximum of 10 branches.
     */
    "branches": Array<
      & Record<string, unknown>
      & ({
        "commit":
          & Record<string, unknown>
          & ({
            "sha": null | string;
            "url": null | string;
          });
        "name": string;
        "protected": boolean;
      })
    >;
    "commit":
      & Record<string, unknown>
      & ({
        /**
         * User
         */
        "author":
          | (
            & Record<string, unknown>
            & ({
              "avatar_url"?: string;
              "deleted"?: boolean;
              "email"?: null | string;
              "events_url"?: string;
              "followers_url"?: string;
              "following_url"?: string;
              "gists_url"?: string;
              "gravatar_id"?: string;
              "html_url"?: string;
              "id"?: RestInt64;
              "login"?: string;
              "name"?: string;
              "node_id"?: string;
              "organizations_url"?: string;
              "received_events_url"?: string;
              "repos_url"?: string;
              "site_admin"?: boolean;
              "starred_url"?: string;
              "subscriptions_url"?: string;
              "type"?: "Bot" | "Organization" | "User";
              "url"?: string;
            })
          )
          | null;
        "comments_url": string;
        "commit":
          & Record<string, unknown>
          & ({
            "author":
              & (
                & Record<string, unknown>
                & ({
                  "date"?: string;
                  "email": null | string;
                  /**
                   * The git author's name.
                   */
                  "name": string;
                  "username"?: string;
                })
              )
              & Record<string, unknown>
              & {
                "date": string;
                "email"?: string;
                "name"?: string;
              };
            "comment_count": RestInt64;
            "committer":
              & (
                & Record<string, unknown>
                & ({
                  "date"?: string;
                  "email": null | string;
                  /**
                   * The git author's name.
                   */
                  "name": string;
                  "username"?: string;
                })
              )
              & Record<string, unknown>
              & {
                "date": string;
                "email"?: string;
                "name"?: string;
              };
            "message": string;
            "tree": Record<string, unknown> & {
              "sha": string;
              "url": string;
            };
            "url": string;
            "verification":
              & Record<string, unknown>
              & ({
                "payload": null | string;
                "reason":
                  | "bad_cert"
                  | "bad_email"
                  | "expired_key"
                  | "gpgverify_error"
                  | "gpgverify_unavailable"
                  | "invalid"
                  | "malformed_signature"
                  | "no_user"
                  | "not_signing_key"
                  | "ocsp_pending"
                  | "unknown_key"
                  | "unknown_signature_type"
                  | "unsigned"
                  | "unverified_email"
                  | "valid";
                "signature": null | string;
                "verified": boolean;
                "verified_at": null | string;
              });
          });
        /**
         * User
         */
        "committer":
          | (
            & Record<string, unknown>
            & ({
              "avatar_url"?: string;
              "deleted"?: boolean;
              "email"?: null | string;
              "events_url"?: string;
              "followers_url"?: string;
              "following_url"?: string;
              "gists_url"?: string;
              "gravatar_id"?: string;
              "html_url"?: string;
              "id"?: RestInt64;
              "login"?: string;
              "name"?: string;
              "node_id"?: string;
              "organizations_url"?: string;
              "received_events_url"?: string;
              "repos_url"?: string;
              "site_admin"?: boolean;
              "starred_url"?: string;
              "subscriptions_url"?: string;
              "type"?: "Bot" | "Organization" | "User";
              "url"?: string;
            })
          )
          | null;
        "html_url": string;
        "node_id": string;
        "parents": Array<
          Record<string, unknown> & {
            "html_url": string;
            "sha": string;
            "url": string;
          }
        >;
        "sha": string;
        "url": string;
      });
    "context": string;
    "created_at": string;
    /**
     * The optional human-readable description added to the status.
     */
    "description": null | string;
    "enterprise"?: EnterpriseWebhooks;
    /**
     * The unique identifier of the status.
     */
    "id": RestInt64;
    "installation"?: SimpleInstallation;
    "name": string;
    "organization"?: OrganizationSimpleWebhooks;
    "repository": RepositoryWebhooks;
    "sender": SimpleUser;
    /**
     * The Commit SHA.
     */
    "sha": string;
    /**
     * The new state. Can be `pending`, `success`, `failure`, or `error`.
     */
    "state": "error" | "failure" | "pending" | "success";
    /**
     * The optional link added to the status.
     */
    "target_url": null | string;
    "updated_at": string;
  });

