/**
 * team added_to_repository event
 */
export type WebhookTeamAddedToRepository =
  & Record<string, unknown>
  & ({
    "action": "added_to_repository";
    "enterprise"?: EnterpriseWebhooks;
    "installation"?: SimpleInstallation;
    "organization": OrganizationSimpleWebhooks;
    /**
     * Repository
     *
     * A git repository
     */
    "repository"?:
      & Record<string, unknown>
      & ({
        /**
         * Whether to allow auto-merge for pull requests.
         */
        "allow_auto_merge"?: boolean;
        /**
         * Whether to allow private forks
         */
        "allow_forking"?: boolean;
        /**
         * Whether to allow merge commits for pull requests.
         */
        "allow_merge_commit"?: boolean;
        /**
         * Whether to allow rebase merges for pull requests.
         */
        "allow_rebase_merge"?: boolean;
        /**
         * Whether to allow squash merges for pull requests.
         */
        "allow_squash_merge"?: boolean;
        "allow_update_branch"?: boolean;
        "archive_url": string;
        /**
         * Whether the repository is archived.
         */
        "archived": boolean;
        "assignees_url": string;
        "blobs_url": string;
        "branches_url": string;
        "clone_url": string;
        "collaborators_url": string;
        "comments_url": string;
        "commits_url": string;
        "compare_url": string;
        "contents_url": string;
        "contributors_url": string;
        "created_at": RestInt64 | string;
        /**
         * The custom properties that were defined for the repository. The keys are the custom property names, and the values are the corresponding custom property values.
         */
        "custom_properties"?: Record<string, unknown>;
        /**
         * The default branch of the repository.
         */
        "default_branch": string;
        /**
         * Whether to delete head branches when pull requests are merged
         */
        "delete_branch_on_merge"?: boolean;
        "deployments_url": string;
        "description": null | string;
        /**
         * Returns whether or not this repository is disabled.
         */
        "disabled"?: boolean;
        "downloads_url": string;
        "events_url": string;
        "fork": boolean;
        "forks": RestInt64;
        "forks_count": RestInt64;
        "forks_url": string;
        "full_name": string;
        "git_commits_url": string;
        "git_refs_url": string;
        "git_tags_url": string;
        "git_url": string;
        /**
         * Whether downloads are enabled.
         */
        "has_downloads": boolean;
        /**
         * Whether issues are enabled.
         */
        "has_issues": boolean;
        "has_pages": boolean;
        /**
         * Whether projects are enabled.
         */
        "has_projects": boolean;
        /**
         * Whether the wiki is enabled.
         */
        "has_wiki": boolean;
        "homepage": null | string;
        "hooks_url": string;
        "html_url": string;
        /**
         * Unique identifier of the repository
         */
        "id": RestInt64;
        "is_template"?: boolean;
        "issue_comment_url": string;
        "issue_events_url": string;
        "issues_url": string;
        "keys_url": string;
        "labels_url": string;
        "language": null | string;
        "languages_url": string;
        /**
         * License
         */
        "license":
          | (
            & Record<string, unknown>
            & ({
              "key": string;
              "name": string;
              "node_id": string;
              "spdx_id": string;
              "url": null | string;
            })
          )
          | null;
        "master_branch"?: string;
        "merges_url": string;
        "milestones_url": string;
        "mirror_url": null | string;
        /**
         * The name of the repository.
         */
        "name": string;
        "node_id": string;
        "notifications_url": string;
        "open_issues": RestInt64;
        "open_issues_count": RestInt64;
        "organization"?: string;
        /**
         * User
         */
        "owner":
          | (
            & Record<string, unknown>
            & ({
              "avatar_url"?: string;
              "deleted"?: boolean;
              "email"?: null | string;
              "events_url"?: string;
              "followers_url"?: string;
              "following_url"?: string;
              "gists_url"?: string;
              "gravatar_id"?: string;
              "html_url"?: string;
              "id": RestInt64;
              "login": string;
              "name"?: string;
              "node_id"?: string;
              "organizations_url"?: string;
              "received_events_url"?: string;
              "repos_url"?: string;
              "site_admin"?: boolean;
              "starred_url"?: string;
              "subscriptions_url"?: string;
              "type"?: "Bot" | "Organization" | "User";
              "url"?: string;
              "user_view_type"?: string;
            })
          )
          | null;
        "permissions"?: Record<string, unknown> & {
          "admin": boolean;
          "maintain"?: boolean;
          "pull": boolean;
          "push": boolean;
          "triage"?: boolean;
        };
        /**
         * Whether the repository is private or public.
         */
        "private": boolean;
        "public"?: boolean;
        "pulls_url": string;
        "pushed_at": RestInt64 | string | null;
        "releases_url": string;
        "role_name"?: null | string;
        "size": RestInt64;
        "ssh_url": string;
        "stargazers"?: RestInt64;
        "stargazers_count": RestInt64;
        "stargazers_url": string;
        "statuses_url": string;
        "subscribers_url": string;
        "subscription_url": string;
        "svn_url": string;
        "tags_url": string;
        "teams_url": string;
        "topics": Array<string>;
        "trees_url": string;
        "updated_at": string;
        "url": string;
        "visibility": "internal" | "private" | "public";
        "watchers": RestInt64;
        "watchers_count": RestInt64;
      });
    "sender"?: SimpleUser;
    "team": WebhooksTeam1;
  });

