/**
 * branch protection rule
 *
 * The branch protection rule. Includes a `name` and all the [branch protection settings](https://docs.github.com/github/administering-a-repository/defining-the-mergeability-of-pull-requests/about-protected-branches#about-branch-protection-settings) applied to branches that match the name. Binary settings are boolean. Multi-level configurations are one of `off`, `non_admins`, or `everyone`. Actor and build lists are arrays of strings.
 */
export type WebhooksRule =
  & Record<string, unknown>
  & ({
    "admin_enforced": boolean;
    "allow_deletions_enforcement_level": "everyone" | "non_admins" | "off";
    "allow_force_pushes_enforcement_level": "everyone" | "non_admins" | "off";
    "authorized_actor_names": Array<string>;
    "authorized_actors_only": boolean;
    "authorized_dismissal_actors_only": boolean;
    "create_protected"?: boolean;
    "created_at": string;
    "dismiss_stale_reviews_on_push": boolean;
    "id": RestInt64;
    "ignore_approvals_from_contributors": boolean;
    "linear_history_requirement_enforcement_level": "everyone" | "non_admins" | "off";
    /**
     * Whether users can pull changes from upstream when the branch is locked. Set to `true` to allow users to pull changes from upstream when the branch is locked. This setting is only applicable for forks.
     */
    "lock_allows_fork_sync"?: boolean;
    /**
     * The enforcement level of the branch lock setting. `off` means the branch is not locked, `non_admins` means the branch is read-only for non_admins, and `everyone` means the branch is read-only for everyone.
     */
    "lock_branch_enforcement_level": "everyone" | "non_admins" | "off";
    "merge_queue_enforcement_level": "everyone" | "non_admins" | "off";
    "name": string;
    "pull_request_reviews_enforcement_level": "everyone" | "non_admins" | "off";
    "repository_id": RestInt64;
    "require_code_owner_review": boolean;
    /**
     * Whether the most recent push must be approved by someone other than the person who pushed it
     */
    "require_last_push_approval"?: boolean;
    "required_approving_review_count": RestInt64;
    "required_conversation_resolution_level": "everyone" | "non_admins" | "off";
    "required_deployments_enforcement_level": "everyone" | "non_admins" | "off";
    "required_status_checks": Array<string>;
    "required_status_checks_enforcement_level": "everyone" | "non_admins" | "off";
    "signature_requirement_enforcement_level": "everyone" | "non_admins" | "off";
    "strict_required_status_checks_policy": boolean;
    "updated_at": string;
  });

