export type TeamsUpdateInOrgInput = {
  path: {
    /**
     * The organization name. The name is not case sensitive.
     */
    "org": string;
    /**
     * The slug of the team name.
     */
    "team_slug": string;
  };
  body?: RestBody<
    "application/json",
    RestJsonValue<
      RestRequestValue<
        & Record<string, unknown>
        & ({
          /**
           * The description of the team.
           */
          "description"?: string;
          /**
           * The name of the team.
           */
          "name"?: string;
          /**
           * The notification setting the team has chosen. Editing teams without specifying this parameter leaves `notification_setting` intact. The options are:
           *  * `notifications_enabled` - team members receive notifications when the team is @mentioned.
           *  * `notifications_disabled` - no one receives notifications.
           */
          "notification_setting"?: "notifications_disabled" | "notifications_enabled";
          /**
           * The ID of a team to set as the parent team.
           */
          "parent_team_id"?: RestInt64 | null;
          /**
           * The slug of a team to set as the parent team. Ignored when `parent_team_id` is also provided.
           */
          "parent_team_slug"?: null | string;
          /**
           * **Closing down notice**. The permission that new repositories will be added to the team with when none is specified.
           */
          "permission"?: "admin" | "pull" | "push";
          /**
           * The level of privacy this team should have. Editing teams without specifying this parameter leaves `privacy` intact. When a team is nested, the `privacy` for parent teams cannot be `secret`. The options are:
           * **For a non-nested team:**
           *  * `secret` - only visible to organization owners and members of this team.
           *  * `closed` - visible to all members of this organization.
           * **For a parent or child team:**
           *  * `closed` - visible to all members of this organization.
           */
          "privacy"?: "closed" | "secret";
        })
      >
    >
  >;
};

